const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
const gamingPaths = /\/(gaming|fortnite|gta|pokemon|call-of-duty|overwatch|apex-legends|valorant|league-of-legends|counter-strike-2|minecraft|world-of-warcraft|diablo|destiny|battlefield|roblox|palworld)\//;
return items.flatMap(({ json }) => (json.urlset?.url ?? []).flatMap((entry) => {
  const articleUrl = entry.loc;
  const publishedAt = entry.lastmod ?? entry["news:news"]?.["news:publication_date"];
  if (!articleUrl || !publishedAt || !gamingPaths.test(articleUrl) || Date.parse(publishedAt) < cutoff) return [];
  const title = articleUrl.split("/").filter(Boolean).at(-1).replace(/-\d+$/, "").replace(/-/g, " ");
  return [{ json: { source: "Dexerto", articleUrl, title, publishedAt: new Date(publishedAt).toISOString(), imageUrl: entry["image:image"]?.["image:loc"] ?? null } }];
}));

function findBody(value) { if (Array.isArray(value)) { for (const x of value) { const found = findBody(x); if (found) return found; } } if (!value || typeof value !== 'object') return null; const types = Array.isArray(value['@type']) ? value['@type'] : [value['@type']]; if (types.some((x) => x === 'NewsArticle' || x === 'Article') && typeof value.articleBody === 'string') return value.articleBody; for (const x of Object.values(value)) { const found = findBody(x); if (found) return found; } return null; }
function decode(text) { return text.replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'\"').replace(/&#39;|&apos;/gi,"'").replace(/&lt;/gi,'<').replace(/&gt;/gi,'>'); }
return items.flatMap(({json}) => { const html=json.articleHtml ?? ''; let body=null; for (const m of html.matchAll(/<script[^>]*type=[\x22']application\/ld\+json[\x22'][^>]*>([\s\S]*?)<\/script>/gi)) { try { body=findBody(JSON.parse(m[1])); if (body) break; } catch {} } if (!body) body=decode((html.match(/<div id=[\x22']article-content[\x22'][^>]*>([\s\S]*?)(?=<div[^>]+id=[\x22']article-note[\x22'])/i)?.[1] ?? '').replace(/<[^>]+>/g,' ')); body=body?.replace(/\s+/g,' ').trim(); if (!body || body.length < 200) return []; const {articleHtml,...article}=json; return [{json:{...article,articleText:body}}]; });

return items.map(({json}) => { const slug=json.articleUrl.split('/').filter(Boolean).at(-1).replace(/-\d+$/,'').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').slice(0,100); const day=json.publishedAt.slice(0,10); const base=`/n8n-youtube-automation/Honi-News/Dexerto-Articles/${day}-${slug}`; const articleId=`dexerto-${day}-${slug}`; const articleMarkdown=`# ${json.title}

