`; const sourceJson=JSON.stringify({article_id:articleId,source:json.source,title:json.title,canonical_url:json.articleUrl,published_at_utc:json.publishedAt,image_url:json.imageUrl,ingested_at_utc:new Date().toISOString()},null,2); return {json:{...json,articleId,articleMarkdown,sourceJson,markdownPath:`${base}.md`,metadataPath:`${base}.json`}}; });
